import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { SampleBase } from './sample-base';
import { PropertyPane } from './property-pane';
import { AccumulationChartComponent, AccumulationSeriesCollectionDirective, AccumulationSeriesDirective, AccumulationLegend, PieSeries, AccumulationTooltip, Inject, AccumulationDataLabel } from '@syncfusion/ej2-react-charts';
import { DropDownListComponent } from '@syncfusion/ej2-react-dropdowns';
import { Browser } from '@syncfusion/ej2/base';
export let data1 = [
    { x: 'China', y: 40, text: 'China: 40' },
    { x: 'Japan', y: 20, text: Browser.isDevice ? 'Japan:<br> 20' : 'Japan: 20' },
    { x: 'Australia', y: 18, text: Browser.isDevice ? 'Australia:<br> 18' : 'Australia: 18' },
    { x: 'France', y: 16, text: 'France: 16' },
    { x: 'Netherlands', y: 15, text: 'Netherlands: 15' },
    { x: 'Great Britain', y: 14, text: 'Great Britain: 14' },
    { x: 'South Korea', y: 13, text: 'South Korea: 13' },
    { x: 'Germany', y: 12, text: Browser.isDevice ? 'Germany:<br> 12' : 'Germany: 12' },
    { x: 'Italy', y: 12, text: Browser.isDevice ? 'Italy:<br> 12' : 'Italy: 12' },
    { x: 'Canada', y: 9, text: Browser.isDevice ? 'CA: 9' : 'Canada: 9' },
    { x: 'Hungary', y: 6, text: Browser.isDevice ? 'HU: 6' : 'Hungary: 6' },
    { x: 'Spain', y: 5, text: 'Spain: 5' },
    { x: 'Kenya', y: 4, text: 'Kenya: 4' },
    { x: 'Brazil', y: 3, text: 'Brazil: 3' }
];
export class Grouping extends SampleBase {
    pie;
    slider;
    dropElement;
    radius = Browser.isDevice ? '40%' : '55%';
    change() {
        this.pie.series[0].groupMode = this.dropElement.value;
        let currentValue = this.dropElement.value === 'Point' ? 9 : 8;
        this.pie.series[0].groupTo = currentValue.toString();
        this.pie.series[0].animation.enable = false;
        document.getElementById('clubtext').innerHTML = currentValue.toString();
        this.slider.value = currentValue.toString();
        this.pie.removeSvg();
        this.pie.refreshSeries();
        this.pie.refreshChart();
    }
    ;
    droplist = [
        { value: 'Point' },
        { value: 'Value' }
    ];
    render() {
        return (<div className='control-pane'>
        <div className='control-section row'>
        <div className='col-lg-9'>
            <AccumulationChartComponent id='pie-chart' ref={pie => this.pie = pie} title='Summer Olympic 2024 - Gold Medals' subTitle='Source: wikipedia.org' load={this.load.bind(this)} tooltip={{ enable: true, header: "", format: "<b>${point.x}</b><br> Gold Medals: <b>${point.y}</b>", enableHighlight: true }} legendSettings={{ visible: false }} enableSmartLabels={true} loaded={this.onChartLoad.bind(this)} enableBorderOnMouseMove={false}>
              <Inject services={[AccumulationLegend, PieSeries, AccumulationTooltip, AccumulationDataLabel]}/>
              <AccumulationSeriesCollectionDirective>
                <AccumulationSeriesDirective dataSource={data1} xName='x' yName='y' name='Summer Olympics' animation={{ enable: true }} explode={true} radius={this.radius} groupTo='9' groupMode='Point' startAngle={-20} endAngle={340} innerRadius='0%' borderRadius={3} border={{ width: 1, color: '#ffffff' }} dataLabel={{ visible: true, name: 'text', position: 'Outside', connectorStyle: { type: 'Curve', length: Browser.isDevice ? '10px' : '20px' }, font: { size: Browser.isDevice ? '8px' : '13px', fontWeight: '600' } }}>
                </AccumulationSeriesDirective>
              </AccumulationSeriesCollectionDirective>
            </AccumulationChartComponent>
        </div>
        <div className='col-lg-3 property-section'>
            <PropertyPane title='Properties'>
              <table id='property' title='Properties' className='property-panel-table' style={{ width: '100%' }}>
              <tbody><tr style={{ height: '50px' }}>
                  <td style={{ width: '50%' }}>
                    <div>Mode: </div>
                  </td>
                  <td style={{ padding: 10, width: '50%' }}>
                    <DropDownListComponent width={120} id="modes" change={this.change.bind(this)} ref={d => this.dropElement = d} dataSource={this.droplist} fields={{ text: 'value', value: 'value' }} value="Point"/>
                  </td>
                </tr>
                <tr style={{ height: '50px' }}>
                  <td style={{ width: '60%' }}>
                    <div id="groupValue">Group To:
                        <p id="clubtext" style={{ fontWeight: 'normal' }}>9</p>
                    </div>
                  </td>
                  <td style={{ width: '40%' }}>
                    <div>
                      <input type="range" name="clubvalue" onChange={this.onClubvalue.bind(this)} ref={slider => this.slider = slider} defaultValue="9" min="0" max="27" id="clubvalue" style={{ marginLeft: '-5px' }} aria-labelledby="Slider"/>
                    </div>
                  </td>
                </tr>
                </tbody>
              </table>
            </PropertyPane>
      </div>
      </div>

      </div>);
    }
    onChartLoad(args) {
        document.getElementById('pie-chart').setAttribute('title', '');
    }
    ;
    onClubvalue(e) {
        let clubvalue = document.getElementById('clubvalue').value;
        this.pie.series[0].groupTo = clubvalue;
        this.pie.series[0].animation.enable = false;
        document.getElementById('clubtext').innerHTML = clubvalue;
        this.pie.removeSvg();
        this.pie.refreshSeries();
        this.pie.refreshChart();
    }
    ;
    load(args) {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Fluent2';
        args.accumulation.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).replace(/-dark/i, "Dark").replace(/contrast/i, 'Contrast');
    }
    ;
}

const root = createRoot(document.getElementById('sample'));
root.render(<Grouping />);

